				var dir = DirAccess.open("/")

				# Prints "true" on a case-insensitive filesystem, "false" otherwise.
				print(dir.is_equivalent("/sbin/md5sum", "/sBin/MD5Sum"))
				
				var icon_1_path = ProjectSettings.globalize_path("res://icon.svg")
